import java.util.Scanner;

public class Main {
    static final long MOD = 1000000007;

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        String s = sc.next();
        sc.close();

        long ans = 0;
        long sumNonzero = 0; // S_{j-1}

        for (int j = 1; j <= n; j++) {
            char ch = s.charAt(j - 1);
            // 判断是否为偶数
            if (ch == '0' || ch == '2' || ch == '4' || ch == '6' || ch == '8') {
                long factor = (n - j + 1) % MOD;
                long contribution = (sumNonzero + j) % MOD;
                ans = (ans + contribution * factor) % MOD;
            }
            // 更新非零位置前缀和
            if (ch != '0') {
                sumNonzero = (sumNonzero + j) % MOD;
            }
        }

        System.out.println(ans);
    }
}
```

